/**
 * Cancellation-poll coverage for the COMPILED aggregate kernel route (parallel-hedge plan, kernel-poll milestone). The
 * 2026-08-19 audit found the aggregate kernels non-resumable (one {@code fill()} runs the whole query) with zero poll
 * sites in their hot loops (FlatRootExists, non-resumable vector tail, ScanQuad/PlanRows, EnumerateDomain, HashProbe
 * chain walk, Intersect, flush) — so a guard or probe deadline could never trip a mispriced compiled winner, which is
 * one half of the HC:10 33-second excursion incident. Each test warms the compiled kernel once, then re-runs the same
 * query inside a PRE-TRIPPED deadline scope: the kernel must abort (the stackless {@link KernelCancelledException} or
 * {@link LmdbNativeProbeDeadlineExceeded} surfacing through the query) instead of running to completion. Fixture sizing
 * keeps every targeted loop above the 1024-iteration poll mask window.
 */
class LmdbNativeKernelAggregatePollPointTest {

	private static final String EX = "http://example.com/poll/";

	private static final String[] PROPERTIES = {
			"rdf4j.lmdb.nativeQueryEngine.enabled",
			"rdf4j.lmdb.janinoCodegen.enabled",
			"rdf4j.lmdb.janinoCodegen.thresholdRows",
			"rdf4j.lmdb.janinoCodegen.synchronous",
			"rdf4j.lmdb.kernelInterpreter.enabled",
			"rdf4j.lmdb.wcoj.enabled",
			"rdf4j.lmdb.factorizedRows.enabled",
			"rdf4j.lmdb.factorizedTail.enabled",
			"rdf4j.lmdb.nativeBatch.enabled",
			"rdf4j.lmdb.packedFtree.enabled",
			"rdf4j.lmdb.prefixRun.enabled",
			"rdf4j.lmdb.parallel.enabled",
			"rdf4j.lmdb.parallel.threads",
			"rdf4j.lmdb.irAggregateParallel.enabled",
			"rdf4j.lmdb.adaptiveProbe.enabled",
			"rdf4j.lmdb.adaptiveHedge.enabled" };

	@TempDir
	File dataDir;

	private final Map<String, String> previousProperties = new HashMap<>();
	private SailRepository repository;

	@BeforeEach
	void setUp() {
		for (String property : PROPERTIES) {
			previousProperties.put(property, System.getProperty(property));
		}
		System.setProperty("rdf4j.lmdb.nativeQueryEngine.enabled", "true");
		System.setProperty("rdf4j.lmdb.janinoCodegen.enabled", "true");
		System.setProperty("rdf4j.lmdb.janinoCodegen.thresholdRows", "0");
		System.setProperty("rdf4j.lmdb.janinoCodegen.synchronous", "true");
		System.setProperty("rdf4j.lmdb.kernelInterpreter.enabled", "true");
		// Pin the ladder so the compiled irAggregate rung serves (cf. LmdbNativeKernelInterpreterWarmupTest), and keep
		// the probe/hedge machinery out of the way — the test enters its own deadline scope.
		System.setProperty("rdf4j.lmdb.wcoj.enabled", "false");
		System.setProperty("rdf4j.lmdb.factorizedRows.enabled", "false");
		System.setProperty("rdf4j.lmdb.factorizedTail.enabled", "false");
		System.setProperty("rdf4j.lmdb.nativeBatch.enabled", "false");
		System.setProperty("rdf4j.lmdb.packedFtree.enabled", "false");
		System.setProperty("rdf4j.lmdb.prefixRun.enabled", "false");
		System.setProperty("rdf4j.lmdb.parallel.enabled", "false");
		System.setProperty("rdf4j.lmdb.parallel.threads", "1");
		System.setProperty("rdf4j.lmdb.irAggregateParallel.enabled", "false");
		System.setProperty("rdf4j.lmdb.adaptiveProbe.enabled", "false");
		System.setProperty("rdf4j.lmdb.adaptiveHedge.enabled", "false");
		KernelExecutionTestAccess.resetCostCalibration();

		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc,ospc")
				.setDirectAdjacencyMode(DirectAdjacencyMode.PREFER)
				.setDirectAdjacencyMaxBytes(1L << 30);
		LmdbStore store = new LmdbStore(dataDir, config);
		repository = new SailRepository(store);
		try (SailRepositoryConnection conn = repository.getConnection()) {
			ValueFactory vf = conn.getValueFactory();
			IRI hasEncounter = vf.createIRI(EX, "hasEncounter");
			IRI code = vf.createIRI(EX, "code");
			// Single transaction, deliberately: per-add autocommit wedges direct adjacency into a revision gap.
			conn.begin();
			for (int i = 0; i < 3000; i++) {
				IRI patient = vf.createIRI(EX, "patient" + i);
				IRI encounter = vf.createIRI(EX, "enc" + i);
				conn.add(patient, hasEncounter, encounter);
				if (i % 2 == 0) {
					conn.add(encounter, code, vf.createLiteral(i));
				}
			}
			conn.commit();
		}
		try {
			assertThat(store.awaitDirectAdjacencyReady(60, java.util.concurrent.TimeUnit.SECONDS)).isTrue();
		} catch (InterruptedException e) {
			Thread.currentThread().interrupt();
			throw new IllegalStateException(e);
		}
	}

	@AfterEach
	void tearDown() {
		if (repository != null) {
			repository.shutDown();
		}
		previousProperties.forEach((property, value) -> {
			if (value == null) {
				System.clearProperty(property);
			} else {
				System.setProperty(property, value);
			}
		});
	}

	@Test
	void countNotExistsKernelAbortsUnderTrippedDeadline() {
		String query = "PREFIX ex: <" + EX + ">\n"
				+ "SELECT (COUNT(DISTINCT ?p) AS ?c) WHERE { ?p ex:hasEncounter ?e ."
				+ " FILTER NOT EXISTS { ?e ex:code ?d } }";
		assertKernelAbortsUnderTrippedDeadline(query);
	}

	@Test
	void groupedAggregateKernelAbortsUnderTrippedDeadline() {
		String query = "PREFIX ex: <" + EX + ">\n"
				+ "SELECT ?p (COUNT(*) AS ?c) WHERE { ?p ex:hasEncounter ?e } GROUP BY ?p";
		assertKernelAbortsUnderTrippedDeadline(query);
	}

	private void assertKernelAbortsUnderTrippedDeadline(String query) {
		long openedBefore = KernelExecutionTestAccess.aggOpened();
		try (SailRepositoryConnection conn = repository.getConnection()) {
			// Warm pass: compiles the kernel synchronously and proves the compiled rung actually serves this query.
			QueryResults.asList(conn.prepareTupleQuery(query).evaluate());
		}
		assertThat(KernelExecutionTestAccess.aggOpened())
				.as("the compiled aggregate rung must serve this query for the poll assertion to be meaningful")
				.isGreaterThan(openedBefore);

		LmdbNativeProbeDeadline deadline = LmdbNativeProbeDeadline.trippableOnly();
		deadline.trip();
		Throwable surfaced = null;
		boolean completed = false;
		try (LmdbNativeProbeDeadline.Scope ignored = LmdbNativeProbeDeadline.enter(deadline)) {
			try (SailRepositoryConnection conn = repository.getConnection()) {
				QueryResults.asList(conn.prepareTupleQuery(query).evaluate());
				completed = true;
			} catch (KernelCancelledException | LmdbNativeProbeDeadlineExceeded | QueryEvaluationException abort) {
				surfaced = abort;
			}
		}
		assertThat(completed)
				.as("a pre-tripped deadline scope must abort the kernel, not let it run to completion")
				.isFalse();
		assertThat(causeChainAborts(surfaced))
				.as("the abort must be the cooperative cancellation, was: " + surfaced)
				.isTrue();
	}

	private static boolean causeChainAborts(Throwable surfaced) {
		for (Throwable cause = surfaced; cause != null; cause = cause.getCause()) {
			if (cause instanceof KernelCancelledException || cause instanceof LmdbNativeProbeDeadlineExceeded) {
				return true;
			}
			if (cause.getCause() == cause) {
				break;
			}
		}
		return false;
	}
}
